-- Mercado Livre refuses emojis in a description (official "Descrição de produtos" page), so from
-- 2026-11-12 SellBridge no longer stores them: the forms refuse them and the imports drop them.
-- This takes out the ones stored before, as `removeEmojis` (packages/shared/src/domain/emoji.ts)
-- does: only the lines with an emoji change, and the bracket lists the same characters (generated
-- from its pattern; ©, ® and ™ stay).
UPDATE "supplier_products" AS "product"
SET "description" = "cleaned"."description", "updated_at" = now()
FROM (
  SELECT
    "id",
    btrim(
      string_agg(
        CASE
